/**
 * Curated buck-converter component catalogs.
 *
 * Values are a reviewed snapshot assembled from public vendor datasheets and
 * selection guides (TI, MPS, XLSEMI, Würth, Coilcraft, Murata, TDK, Vishay).
 * They are intentionally conservative and MUST be re-verified against the
 * current datasheet before ordering hardware — the UI shows this note on every
 * result. Nothing here is generated by a model.
 */
import type { IcCatalogEntry, PassiveSelection } from './types';

export interface InductorPart {
  part: string;
  vendor: string;
  inductanceH: number;
  isatA: number;
  irmsA: number;
  dcrOhm: number;
  sizeMm: string;
  note: string;
}

export interface CapacitorPart {
  part: string;
  vendor: string;
  capacitanceF: number;
  voltageV: number;
  dielectric: string;
  packageName: string;
  /** Fraction of nominal capacitance remaining at the rated voltage (curated). */
  effectiveAtRatedBias: number;
  esrOhm: number;
  rippleCurrentA: number;
  note: string;
}

export interface DiodePart {
  part: string;
  vendor: string;
  vrV: number;
  ifA: number;
  vfV: number;
  packageName: string;
  note: string;
}

